import sqlite3, json, re
RUN="/Users/jbotts/frus-analysis/c3s/runs/s5/"
OUT=RUN+"refuter/"
DB="/Users/jbotts/frus-analysis/c3/frus-copy-2026-10-25.db"
db=sqlite3.connect(f"file:{DB}?mode=ro", uri=True)
ED2=('frus1951-54IranEd2','frus1969-76ve15p2Ed2')
def q(s,*a): return db.execute(s,a).fetchall()
print("N1 coverage:", q("SELECT COUNT(DISTINCT volume_id), COUNT(*), SUM(is_front_matter), SUM(is_editorial_note) FROM document_cache"))
print("non-apparatus:", q("SELECT COUNT(*) FROM document_cache WHERE is_front_matter=0 AND is_editorial_note=0"))
print("both flags set:", q("SELECT COUNT(*) FROM document_cache WHERE is_front_matter=1 AND is_editorial_note=1"))
print("Ed2 non-apparatus:", q("SELECT COUNT(*) FROM document_cache WHERE is_front_matter=0 AND is_editorial_note=0 AND volume_id IN (?,?)",*ED2))
n2=q("SELECT COUNT(*), COUNT(DISTINCT volume_id) FROM document_cache WHERE is_front_matter=0 AND is_editorial_note=0 AND volume_id NOT IN (?,?)",*ED2)
print("N2 (Ed2 suppressed): docs, vols:", n2)
FAM='body_text:(corrupt OR brib* OR graft OR embezzl OR kickback OR "questionable payments" OR "illicit payments")'
rows=q("SELECT c.volume_id, c.document_id FROM frus_documents f JOIN document_cache c ON c.rowid=f.rowid WHERE frus_documents MATCH ? AND c.is_front_matter=0 AND c.is_editorial_note=0",FAM)
print("N3 family before Ed2: docs, vols:", len(rows), len({v for v,_ in rows}))
hits=sorted((v,d) for v,d in rows if v not in ED2)
print("N3 family after Ed2: docs, vols:", len(hits), len({v for v,_ in hits}))
print("ratio hits/N2 = %.4f%%" % (100*len(hits)/n2[0][0]))
json.dump(hits, open(OUT+"hits_ed2suppressed.json","w"))
sess=set(map(tuple,json.load(open(RUN+"core_hits.json"))))
print("session core_hits.json n:", len(sess), "== my pre-Ed2 set:", sess==set(map(tuple,rows)))
sess2=set(map(tuple,json.load(open(RUN+"core_hits_ed2suppressed.json"))))
print("session core_hits_ed2suppressed.json n:", len(sess2), "== my post-Ed2 set:", sess2==set(hits))
co=q("SELECT c.volume_id, c.document_id FROM frus_documents f JOIN document_cache c ON c.rowid=f.rowid WHERE frus_documents MATCH 'body_text:corrupt' AND c.is_front_matter=0 AND c.is_editorial_note=0")
print("corrupt-only before Ed2:", len(co), len({v for v,_ in co}), "after:", len([1 for v,_ in co if v not in ED2]), len({v for v,_ in co if v not in ED2}))
for t in ['"Department of State"','"ZZZ_IMPOSSIBLE_ZZZ"']:
    print("control", t, q("SELECT COUNT(*), COUNT(DISTINCT c.volume_id) FROM frus_documents f JOIN document_cache c ON c.rowid=f.rowid WHERE frus_documents MATCH ? AND c.is_front_matter=0 AND c.is_editorial_note=0",'body_text:'+t))
print("volume(s) missing the positive control:", q("""SELECT volume_id FROM document_cache GROUP BY volume_id EXCEPT SELECT DISTINCT c.volume_id FROM frus_documents f JOIN document_cache c ON c.rowid=f.rowid WHERE frus_documents MATCH 'body_text:"Department of State"'"""))
idx=[int(i*len(hits)/40) for i in range(40)]
samp=[hits[i] for i in idx]
s40=json.load(open(RUN+"sample40.json"))
sess_samp=[(o["v"],o["d"]) for o in s40]
print("sample 40 pairs equal to session's sample40.json:", samp==sess_samp)
STRICT=re.compile(r"\b(corruption|corrupt|bribery|bribe|bribes|graft|embezzlement|kickbacks?|questionable payments|illicit payments)\b")
TOL=re.compile(r"(corrupt\w*|brib\w*|graft\w*|embezzl\w*|kickback\w*|(?:questionable|illicit)[\s\-,().]+payments?)", re.I)
s_ok=t_ok=0
for v,d in samp:
    r=q("SELECT header,coalesce(dateline,''),coalesce(source_note,''),body_text FROM document_cache WHERE volume_id=? AND document_id=?",v,d)[0]
    t=" ".join((r[0]+" "+r[1]+" "+r[2]+" "+r[3]).split())
    s_ok+=bool(STRICT.search(t)); t_ok+=bool(TOL.search(t))
print("STRICT", s_ok, "of 40; TOLERANT", t_ok, "of 40")
coding=json.load(open(RUN+"sample40_coding.json"))
print("session coding: referent_ok", sum(1 for c in coding if c["referent_ok"]), "decision", sum(1 for c in coding if c["decision_or_conduct_link"]), "| coding pairs == sample:", [c["pair"] for c in coding]==[f"{v}/{d}" for v,d in samp])
print("decision=Y pairs:", [c["pair"] for c in coding if c["decision_or_conduct_link"]])
coll=json.load(open(RUN+"collection.fruscollection"))
pairs=[(e["volumeId"],e["documentId"]) for e in coll["entries"] if e["kind"]=="document"]
print("collection documents:", len(pairs), "distinct:", len(set(pairs)), "volumes:", len({v for v,_ in pairs}))
print("collection volumes:", sorted({v for v,_ in pairs}))
db.execute("CREATE TEMP TABLE coll(volume_id TEXT, document_id TEXT)"); db.executemany("INSERT INTO coll VALUES(?,?)",pairs)
print("date span of the 38:", q("SELECT MIN(d.date_iso), MAX(d.date_iso), COUNT(d.date_iso) FROM coll c LEFT JOIN document_dates d ON d.volume_id=c.volume_id AND d.document_id=c.document_id"))
print("undated among 38:", q("SELECT c.volume_id||'/'||c.document_id FROM coll c LEFT JOIN document_dates d ON d.volume_id=c.volume_id AND d.document_id=c.document_id WHERE d.date_iso IS NULL"))
hs=set(hits)
print("collection docs in family hit set:", sum(1 for p in pairs if p in hs), "not in:", [p for p in pairs if p not in hs])
print("A1 source rows:")
for r in q("SELECT COALESCE(s.repository,'(no source row)') repo, COALESCE(s.record_group,'-') rg, COALESCE(s.citation_era,'-') era, COUNT(*) n, group_concat(c.volume_id||'/'||c.document_id,' ') docs FROM coll c LEFT JOIN document_sources s ON s.volume_id=c.volume_id AND s.document_id=c.document_id GROUP BY 1,2,3 ORDER BY n DESC"): print("  ",r)
print("with a document_sources row:", q("SELECT COUNT(*) FROM coll c JOIN document_sources s ON s.volume_id=c.volume_id AND s.document_id=c.document_id"))
print("RG59 central files (decimal+subject_numeric):", q("SELECT COUNT(*) FROM coll c JOIN document_sources s ON s.volume_id=c.volume_id AND s.document_id=c.document_id WHERE s.record_group='59' AND s.citation_era IN ('decimal','subject_numeric')"))
print("raw source lines of the non-Central-Files rows:")
for r in q("SELECT c.volume_id||'/'||c.document_id, s.repository, s.record_group, s.lot_file, s.lot_file_norm, s.series_name, s.citation_era, s.raw_text FROM coll c LEFT JOIN document_sources s ON s.volume_id=c.volume_id AND s.document_id=c.document_id WHERE s.citation_era IS NULL OR s.citation_era NOT IN ('decimal','subject_numeric')"): print("  ",r)
print("source_note column of frus1893/d628:", q("SELECT source_note, substr(body_text,1,200) FROM document_cache WHERE volume_id='frus1893' AND document_id='d628'"))
db.execute("CREATE TEMP TABLE hit(volume_id TEXT, document_id TEXT)"); db.executemany("INSERT INTO hit VALUES(?,?)",hits)
print("A2 came-from over hits (top 14):")
for r in q("SELECT COALESCE(s.repository,'(none)') repo, COALESCE(s.record_group,'-') rg, s.citation_era, COUNT(*) FROM hit h LEFT JOIN document_sources s ON s.volume_id=h.volume_id AND s.document_id=h.document_id GROUP BY 1,2,3 ORDER BY 4 DESC LIMIT 14"): print("  ",r)
print("A2 pointed-at by anchor:", q("SELECT e.anchor, COUNT(*), COUNT(DISTINCT e.volume_id||'/'||e.document_id) FROM hit h JOIN external_citations e ON e.volume_id=h.volume_id AND e.document_id=h.document_id GROUP BY 1 ORDER BY 2 DESC"))
print("A2 pointed-at targets (top 14):")
for r in q("SELECT e.repository, COALESCE(NULLIF(e.collection,''),NULLIF(e.lot_file_norm,''),'(decimal/class)') tgt, COUNT(*) FROM hit h JOIN external_citations e ON e.volume_id=h.volume_id AND e.document_id=h.document_id WHERE e.anchor IN ('lotFile','presidentialLibrary') GROUP BY 1,2 ORDER BY 3 DESC LIMIT 14"): print("  ",r)
print("earliest external_citations document date:", q("SELECT MIN(d.date_iso) FROM external_citations e JOIN document_dates d ON d.volume_id=e.volume_id AND d.document_id=e.document_id"))
print("CIA came-from over hits:", q("SELECT COUNT(*) FROM hit h JOIN document_sources s ON s.volume_id=h.volume_id AND s.document_id=h.document_id WHERE s.repository='Central Intelligence Agency'"))
den=dict(q("SELECT substr(d.date_iso,1,3)||'0s', COUNT(*) FROM document_cache c JOIN document_dates d ON d.volume_id=c.volume_id AND d.document_id=c.document_id WHERE c.is_front_matter=0 AND c.is_editorial_note=0 AND c.volume_id NOT IN (?,?) AND d.date_iso IS NOT NULL GROUP BY 1",*ED2))
print("decade denominators 1840s,1850s,1990s:", den.get('1840s'), den.get('1850s'), den.get('1990s'))
print("1990s volumes:", q("SELECT c.volume_id, COUNT(*) FROM document_cache c JOIN document_dates d ON d.volume_id=c.volume_id AND d.document_id=c.document_id WHERE c.is_front_matter=0 AND c.is_editorial_note=0 AND d.date_iso>='1990' GROUP BY 1"))
print("family hits dated >=1990:", q("SELECT COUNT(*) FROM hit h JOIN document_dates d ON d.volume_id=h.volume_id AND d.document_id=h.document_id WHERE d.date_iso>='1990'"))
print("DoS dated >=1990:", q("""SELECT COUNT(*) FROM frus_documents f JOIN document_cache c ON c.rowid=f.rowid JOIN document_dates d ON d.volume_id=c.volume_id AND d.document_id=c.document_id WHERE frus_documents MATCH 'body_text:"Department of State"' AND d.date_iso>='1990' AND c.is_front_matter=0 AND c.is_editorial_note=0"""))
